!function(t){function r(r){for(var e,n,p=r[0],o=r[1],u=r[2],k=0,g=[];k<p.length;k++)n=p[k],Object.prototype.hasOwnProperty.call(m,n)&&m[n]&&g.push(m[n][0]),m[n]=0;for(e in o)Object.prototype.hasOwnProperty.call(o,e)&&(t[e]=o[e]);for(c&&c(r);g.length;)g.shift()();return i.push.apply(i,u||[]),a()}function a(){for(var t,r=0;r<i.length;r++){for(var a,n=i[r],p=!0,o=1;o<n.length;o++)a=n[o],0!==m[a]&&(p=!1);p&&(i.splice(r--,1),t=e(e.s=n[0]))}return t}function e(r){if(n[r])return n[r].exports;var a=n[r]={i:r,l:!1,exports:{}};return t[r].call(a.exports,a,a.exports,e),a.l=!0,a.exports}var n={},m={8:0},i=[];e.m=t,e.c=n,e.d=function(t,r,a){e.o(t,r)||Object.defineProperty(t,r,{enumerable:!0,get:a})},e.r=function(t){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(t,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(t,"__esModule",{value:!0})},e.t=function(t,r){if(1&r&&(t=e(t)),8&r)return t;if(4&r&&"object"==typeof t&&t&&t.__esModule)return t;var a=Object.create(null);if(e.r(a),Object.defineProperty(a,"default",{enumerable:!0,value:t}),2&r&&"string"!=typeof t)for(var n in t)e.d(a,n,function(r){return t[r]}.bind(null,n));return a},e.n=function(t){var r=t&&t.__esModule?function(){return t.default}:function(){return t};return e.d(r,"a",r),r},e.o=function(t,r){return Object.prototype.hasOwnProperty.call(t,r)},e.p="";var p=window.webpackJsonp=window.webpackJsonp||[],o=p.push.bind(p);p.push=r,p=p.slice();for(var u=0;u<p.length;u++)r(p[u]);var c=o;i.push([27,0]),a()}({27:function(t,r,a){"use strict";a.r(r);var e=a(0);Object(e.a)("uk","army",a(28),a(1))},28:function(t){t.exports=JSON.parse('{"category":[{"name":"英国","link":"uk_shortcut"},{"name":"陆战武器","link":"uk_army"},{"name":"坦克","link":"uk_army#uk_army_tank"}],"model":"A27M“克伦威尔”巡航坦克","description":"<h6>综述：</h6><p>“克伦威尔”（Cromwell）巡航坦克是1943年1月正式投产的一种中型巡航坦克，它生产了由“Ⅰ-VIII”共8个型号；“克伦威尔”坦克沿用了“十字军”巡航坦克的“克里斯蒂”独立圆柱螺旋弹簧悬挂系统，并首先装上了性能可靠的大功率“流星”汽油发动机，使其成为车速最快的巡航坦克。武器方面，早期的“克伦威尔”巡航坦克装备的是6磅火炮、后改装75mm火炮，也有部分装上了95mm榴弹炮；坦克在防护上也得到加强，后期的正面装甲厚度也达到了102mm。至二战结束，“克伦威尔”巡航坦克一共生产了4016辆，是二战后期英军装甲部队的重要装备，为盟军最后的胜利出了不少力。</p>","part1title":"系列型号","part1description":"","part1content":[{"image":"{{text}}MK.VIII A27M“克伦威尔”Ⅰ型坦克{{image}}imgs/uk/army/uk_army_tankcw_11.jpg{{text}}MK.VIII A27M“克伦威尔”ⅠB型坦克{{image}}imgs/uk/army/uk_army_tankcw_12.jpg{{text}MK.VIII A27M“克伦威尔”Ⅲ型坦克{{image}}imgs/uk/army/uk_army_tankcw_13.jpg","description":"<h6>“克伦威尔”Ⅰ、Ⅱ、Ⅲ型巡航坦克</h6><p>Ⅰ、Ⅱ、Ⅲ型坦克车体与炮塔多为铆接结构，坦克战斗全重约为28t，乘员5人，动力系统安装流星系列V-12水冷式汽油发动机，功率600匹马力，传动系统有4个前进挡和1个后退挡，悬挂系统采用克里斯蒂装置，速度达64km/h。主要武器是1门6磅（57mm）火炮（只能发射穿甲弹），辅助武器有二挺机枪，一挺为炮塔前方7.92mm同轴机枪，另一挺为车体前方7.92mm机枪。最厚装甲为76mm。</p>","caption":""},{"image":"{{text}}MK.VIII A27M“克伦威尔”Ⅳ型坦克{{image}}imgs/uk/army/uk_army_tankcw_14.jpg{{text}}MK.VIII A27M“克伦威尔”Ⅳ型坦克<br>1944年6月，法国诺曼底战场，英军第11装甲师的一辆编号为“T187827”的“克伦威尔”Ⅳ型坦克。{{image}}imgs/uk/army/uk_army_tankcw_15.jpg{{text}}MK.VIII A27M“克伦威尔”Ⅴ型坦克（编号：T21367）{{image}}imgs/uk/army/uk_army_tankcw_16.jpg{{text}}MK.VIII A27M“克伦威尔”Ⅵ型坦克{{image}}imgs/uk/army/uk_army_tankcw_17.jpg{{text}}MK.VIII A27M“克伦威尔”VII型坦克<br>1944年6月，法国诺曼底战场，英军第11装甲师的一辆“克伦威尔”VII型坦克。{{image}}imgs/uk/army/uk_army_tankcw_18.jpg{{text}}1944年6月，英军第8军第11装甲师的一辆编号为T187740的“克伦威尔”巡航坦克。{{image}}imgs/uk/army/uk_army_tankcw_19.jpg","description":"<h6>“克伦威尔”Ⅳ型-VIII型坦克</h6><p>“克伦威尔”Ⅳ型及Ⅵ型号的车体与炮塔仍采用铆接结构，Ⅴ型和VIII型采用了较精细的焊接结构；这几款坦克的主要变化是进行了主炮更换和装甲加厚，其中Ⅳ、Ⅴ、VII型更换了75mm火炮（能发射穿甲弹和榴弹），增加了炮口制退器，Ⅵ型和VIII型换装了95mm榴弹炮；而VII、VIII型的最厚装甲也加大至102mm。</p><p>其中Ⅳ型的坦克参数是：</p><p>车长：6.35m，车宽：2.91m, 车高：2.49m，车重：约28.0t，乘员：5人；</p><p>最高车速：64km/h，最大行程：270km；</p><p>装甲厚度：8-76mm；</p><p>主要武器装备：一门75mm火炮。</p>","caption":""}],"part2title":"战场上的“克伦威尔”巡航坦克","part2description":"<p>1944年6月盟军在法国诺曼底登陆，“克伦威尔”巡航坦克随英军第11装甲师等装甲部队正式投入战斗，从登上诺曼底开始，一路征战法国、比利时、荷兰，一直到进入德国作战。“克伦威尔”巡航坦克的火力与装甲相对德军重型坦克还是显得较弱，1944年6月中旬，英军第7装甲师的一个克伦威尔坦克中队就遭受到德国武装党卫军上尉迈克尔.魏特曼率领的101重装团2连一支虎式坦克分队的伏击，在迈克尔.魏特曼自己的坐驾被击毁前，他个人就击毁了英军的6辆坦克。但“克伦威尔”坦克也会用多辆坦克和其它型号的坦克一起，以速度和机动与德军重型坦克周旋，在波卡基会战中，1辆“克伦威尔”与2辆“莹火虫”坦克配合，在德军一辆虎式坦克刚进入射界就率先开火，3发炮弹就将该辆虎式坦克摧毁。但由于装备部队较晩，再加上当时盟军已有大量性能比“克伦威尔”巡航坦克更好的坦克出现在战场，因此，该坦克在二战中的作用还是有限的。</p>","part2content":[{"image":"imgs/uk/army/uk_army_tankcw_31.jpg","description":"1944年6月，法国诺曼底，一辆被登陆艇运到奥哈马海滩的英军“克伦威尔”巡航坦克陷入泥沙中被困。","caption":""},{"image":"imgs/uk/army/uk_army_tankcw_32.jpg","description":"1944年6月，法国诺曼底，一辆英军“克伦威尔”巡航坦克在涉水抢滩登陆。","caption":""},{"image":"imgs/uk/army/uk_army_tankcw_33.jpg","description":"1944年6月，一队英军“克伦威尔”巡航坦克正在法国诺曼底镇行进。这辆编号为T187740的坦克印有英军第11装甲师的“公牛”标志。","caption":""},{"image":"imgs/uk/army/uk_army_tankcw_34.jpg","description":"1944年法国战场，一辆英军“克伦威尔”Ⅵ型巡航坦克停靠在树荫下待命。","caption":""},{"image":"imgs/uk/army/uk_army_tankcw_35.jpg","description":"1944年6月13日，在进攻法国一城镇的战斗中，被德军击毁的一辆英军“克伦威尔”Ⅳ型巡航坦克。","caption":""},{"image":"imgs/uk/army/uk_army_tankcw_36.jpg","description":"1944年6月，法国战场，英军第11装甲师在诺曼底登陆后，所属的第2北安普敦郡约曼利团的“克伦威尔”巡航坦克群正沿公路继续向前推进。","caption":""},{"image":"imgs/uk/army/uk_army_tankcw_37.jpg","description":"1944年7月，法国卡昂战场，英军第2集团军发动“古德伍德”行动，准备夺取卡昂，并继续向法莱斯推。一队英军“克伦威尔”巡航坦克正在集结待命出发。","caption":""},{"image":"imgs/uk/army/uk_army_tankcw_38.jpg","description":"1944年8月，一辆英军“克伦威尔”Ⅳ型巡航坦克正停靠在一个法国城镇的十字路口上。","caption":""},{"image":"imgs/uk/army/uk_army_tankcw_39.jpg","description":"1944年8月，在法国卡昂附近，波兰装甲师一辆“克伦威尔”Ⅳ型巡航坦克在一门德军遗弃的88mm高炮旁经过。","caption":""},{"image":"imgs/uk/army/uk_army_tankcw_40.jpg","description":"1945年5月，盟军已攻进德国，一辆英军第11装甲师的“克伦威尔”巡航坦克正在沿德国公路向汉堡进发，路旁标志牌上提示离汉堡还有38km。","caption":""}]}')}});